<?php
$taxText??=static function(string $source,array $values=[]):string{foreach($values as$key=>$value)if(is_scalar($value))$source=str_replace('{'.$key.'}',(string)$value,$source);return$source;};
$annualRowsEnabled=isset($annualTaxRoute);
// Embedded in the preparation form. Keep raw inputs so failed requests lose no draft.
$taxNotesInput=is_array($taxNotesInput??null)?$taxNotesInput:[];
$taxNotesFrom=(int)($taxNotesFrom??date('Y')-1);$taxNotesTo=(int)($taxNotesTo??$taxNotesFrom);
$taxNotesYears=$taxNotesFrom>=2000&&$taxNotesTo>=$taxNotesFrom&&$taxNotesTo<=(int)date('Y')&&$taxNotesTo-$taxNotesFrom<=2?range($taxNotesFrom,$taxNotesTo):[];
foreach(array_slice(array_keys($taxNotesInput),0,6) as $taxNotesKey)if(preg_match('/^[0-9]{4}$/D',(string)$taxNotesKey)&&(int)$taxNotesKey>=2000&&(int)$taxNotesKey<=(int)date('Y')&&!in_array((int)$taxNotesKey,$taxNotesYears,true))$taxNotesYears[]=(int)$taxNotesKey;
$taxNotesValue=static fn(array $row,string $key,string $default=''):string=>is_string($row[$key]??null)?$row[$key]:$default;
$taxNotesSelect=static function(string $name,string $label,array $options,string $value,array $attrs=[])use($taxText) { ?>
<label><?= e($taxText($label)) ?><select class="form-control" name="<?= e($name) ?>"<?php foreach($attrs as $attr=>$attrValue): ?> <?= e($attr) ?>="<?= e($attrValue) ?>"<?php endforeach ?>><?php foreach($options as $key=>$text): ?><option value="<?= e((string)$key) ?>" <?= $value===(string)$key?'selected':'' ?>><?= e($taxText((string)$key==='unknown'?'Weiß ich nicht – prüfen lassen':$text)) ?></option><?php endforeach ?></select></label>
<?php };
$taxNotesAmount=static function(string $name,string $label,string $value,bool $required=false)use($taxText) { ?>
<label><?= e($taxText($label)) ?><input class="form-control" name="<?= e($name) ?>" value="<?= e($value) ?>" type="text" inputmode="decimal" maxlength="30" placeholder="<?= e($taxText('Leer = noch unbekannt')) ?>" data-tax-amount<?= $required?' data-tax-required':'' ?>></label>
<?php };
$taxNotesReserveRow=static function(array $row,string $index,int $year)use($taxNotesValue,$taxNotesAmount,$taxText,$annualRowsEnabled){$base='tax_year_notes['.$year.'][reserves]['.$index.']'; ?>
<fieldset class="tax-notes-row" data-tax-notes-row><legend><?= e($taxText('Rücklage')) ?> <span data-tax-row-number><?= ctype_digit($index)?(int)$index+1:'' ?></span></legend>
<label><?= e($taxText('Wofür wird das Geld zurückgelegt?')) ?><input class="form-control" name="<?= e($base.'[purpose]') ?>" value="<?= e($taxNotesValue($row,'purpose')) ?>" maxlength="200" data-tax-required placeholder="<?= e($taxText('Zum Beispiel eine geplante Reparatur')) ?>"></label>
<label><?= e($taxText('Begründung und zugehöriger Nachweis')) ?><textarea class="form-control" name="<?= e($base.'[reason]') ?>" rows="3" maxlength="1500" data-tax-required placeholder="<?= e($taxText('Warum besteht die Rücklage? Auf welche Berechnung oder Unterlagen stützt sie sich?')) ?>"><?= e($taxNotesValue($row,'reason')) ?></textarea></label>
<div class="form-grid"><?php foreach(['opening'=>'Anfangsbestand am 1. Januar (EUR)','addition'=>'Im Jahr hinzugekommen (EUR)','use'=>'Im Jahr verwendet oder aufgelöst (EUR)','closing'=>'Endbestand am 31. Dezember (EUR)'] as $key=>$label)$taxNotesAmount($base.'['.$key.']',$label,$taxNotesValue($row,$key)); ?></div>
<p class="tax-notes-error" data-tax-reserve-warning role="alert" hidden></p><p class="muted"><?= e($taxText('Endbestand = Anfangsbestand + hinzugekommen − verwendet oder aufgelöst. Unbekannte Beträge leer lassen; 0 bedeutet ausdrücklich null Euro.')) ?></p><button type="<?=$annualRowsEnabled?'submit':'button'?>" <?php if($annualRowsEnabled):?>name="annual_tax_rows" value="<?=e('remove:reserves:'.$year.':'.$index)?>" formnovalidate<?php endif?> class="btn btn-outline theme-secondary button secondary" data-tax-remove-row><?= e($taxText('Diese Rücklage entfernen')) ?></button>
</fieldset>
<?php };
$taxNotesCorrectionRow=static function(array $row,string $index,int $year)use($taxNotesValue,$taxNotesAmount,$taxNotesSelect,$taxText,$annualRowsEnabled){$base='tax_year_notes['.$year.'][corrections]['.$index.']'; ?>
<fieldset class="tax-notes-row" data-tax-notes-row><legend><?= e($taxText('Manuelle Korrektur')) ?> <span data-tax-row-number><?= ctype_digit($index)?(int)$index+1:'' ?></span></legend>
<div class="form-grid"><?php $taxNotesSelect($base.'[sphere]','Zu welchem Vereinsbereich gehört die Korrektur?',[''=>'Bitte auswählen','1'=>'1 · Ideeller Bereich','2'=>'2 · Vermögensverwaltung','3'=>'3 · Zweckbetrieb','4'=>'4 · Wirtschaftlicher Geschäftsbetrieb'],$taxNotesValue($row,'sphere'),['data-tax-required'=>'']);$taxNotesSelect($base.'[direction]','Wie wirkt die Korrektur?',[''=>'Bitte auswählen','add'=>'Hinzurechnung: Betrag ergänzen','subtract'=>'Abzug: Betrag abziehen'],$taxNotesValue($row,'direction'),['data-tax-required'=>'']);$taxNotesAmount($base.'[amount]','Betrag der Korrektur (EUR)',$taxNotesValue($row,'amount'),true); ?></div>
<label><?= e($taxText('Warum wird korrigiert? Welche Unterlage gehört dazu?')) ?><textarea class="form-control" name="<?= e($base.'[reason]') ?>" rows="3" maxlength="1500" data-tax-required><?= e($taxNotesValue($row,'reason')) ?></textarea></label><button type="<?=$annualRowsEnabled?'submit':'button'?>" <?php if($annualRowsEnabled):?>name="annual_tax_rows" value="<?=e('remove:corrections:'.$year.':'.$index)?>" formnovalidate<?php endif?> class="btn btn-outline theme-secondary button secondary" data-tax-remove-row><?= e($taxText('Diese Korrektur entfernen')) ?></button>
</fieldset>
<?php }; ?>
<link rel="stylesheet" href="tax-year-notes.css?v=2">
<section class="tax-year-notes" <?php if($annualRowsEnabled):?>data-annual-tax-notes-messages="<?=e(json_encode(['amount'=>$taxText('Bitte einen gültigen Eurobetrag eingeben, zum Beispiel 1.234,56. Unbekannte Beträge leer lassen.'),'reserve'=>$taxText('Endbestand prüfen: Anfangsbestand plus Zugang minus Verwendung muss den Endbestand ergeben.')],JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR))?>"<?php endif?> data-tax-year-notes aria-labelledby="tax-year-notes-heading">
<h2 id="tax-year-notes-heading"><?= e($taxText('Jahresangaben ergänzen')) ?></h2>
<p><?= e($taxText('Nur fehlende Jahresangaben ergänzen.')) ?> <strong><?= e($taxText('Unbekannte Beträge leer lassen; 0 bedeutet geprüft null Euro.')) ?></strong></p>
<?php foreach($taxNotesYears as $taxNotesYear):$taxNotesRow=is_array($taxNotesInput[$taxNotesYear]??null)?$taxNotesInput[$taxNotesYear]:[];$taxNotesBase='tax_year_notes['.$taxNotesYear.']';$taxNotesOutside=$taxNotesYear<$taxNotesFrom||$taxNotesYear>$taxNotesTo; ?>
