<label><?= e($taxText('Was fehlt noch oder welche Unterlagen haben Sie geprüft?')) ?><textarea class="form-control" name="<?= e($taxNotesBase.'[record_completeness_note]') ?>" rows="3" maxlength="2000"><?= e($taxNotesValue($taxNotesRow,'record_completeness_note')) ?></textarea></label></details>
<details class="tax-notes-step"><summary><?=e($taxText('2. Offene Rechnungen und Vermögen am 31. Dezember {year}',['year'=>$taxNotesYear]))?></summary>
<div class="form-grid"><?php foreach(['receivables'=>'Was stand dem Verein noch zu? · offene Forderungen in EUR','liabilities'=>'Was musste der Verein noch bezahlen? · offene Schulden in EUR','fixed_assets_book_value'=>'Gegenstände nach Abschreibungen · geprüfter Buchwert in EUR','other_assets'=>'Weiteres Vermögen ohne Bank, Kasse und Gegenstände · EUR'] as $key=>$label)$taxNotesAmount($taxNotesBase.'['.$key.']',$label,$taxNotesValue($taxNotesRow,$key)); ?></div>
<details><summary><?= e($taxText('Welche Werte gehören hierher?')) ?></summary><p><?= e($taxText('Noch unbezahlte Rechnungen und andere offene Ansprüche oder Schulden zum Jahresende. Für Gegenstände den geprüften Wert nach Abschreibungen verwenden, keinen geschätzten Verkaufspreis. Bank und Kasse sind bereits erfasst; nicht doppelt zählen.')) ?></p></details>
<label><?= e($taxText('Nachweis oder noch offene Frage')) ?><textarea class="form-control" name="<?= e($taxNotesBase.'[valuation_note]') ?>" rows="3" maxlength="2000" placeholder="<?= e($taxText('Zum Beispiel geprüfte Aufstellung mit Datum')) ?>"><?= e($taxNotesValue($taxNotesRow,'valuation_note')) ?></textarea></label></details>
<details class="tax-notes-step" data-tax-notes-section <?=!empty($taxNotesExpand[$taxNotesYear]['reserves'])?'open':''?>><summary><?= e($taxText('3. Wurde Geld als Rücklage zurückgelegt?')) ?></summary>
<?php $taxNotesSelect($taxNotesBase.'[reserves_status]','Rücklagenstand',['unknown'=>'Noch offen','none'=>'Nach eigener Prüfung keine Rücklagen','listed'=>'Rücklagen einzeln erfassen'],$taxNotesValue($taxNotesRow,'reserves_status','unknown'),['data-tax-section-choice'=>'listed']); ?>
<details data-tax-section-body <?= ($taxNotesValue($taxNotesRow,'reserves_status')==='listed'||!empty($taxNotesExpand[$taxNotesYear]['reserves']))?'open':'' ?>><summary><?= e($taxText('Rücklagen erfassen')) ?></summary><p><?= e($taxText('Zweck und Nachweis der Rücklage angeben. Die Zulässigkeit muss geklärt sein.')) ?></p>
<div data-tax-notes-list="reserves" data-tax-max="10"><?php $taxNotesReserves=is_array($taxNotesRow['reserves']??null)?array_slice(array_values($taxNotesRow['reserves']),0,10):[];if(!$taxNotesReserves)$taxNotesReserves=[[]];foreach($taxNotesReserves as $i=>$r)$taxNotesReserveRow(is_array($r)?$r:[],(string)$i,$taxNotesYear); ?></div>
<template data-tax-notes-template="reserves"><?php $taxNotesReserveRow([],'__INDEX__',$taxNotesYear); ?></template><button type="<?=$annualRowsEnabled?'submit':'button'?>" <?php if($annualRowsEnabled):?>name="annual_tax_rows" value="<?=e('add:reserves:'.$taxNotesYear)?>" formnovalidate<?php endif?> class="btn btn-outline theme-secondary button secondary" data-tax-add-row="reserves"><?= e($taxText('Weitere Rücklage hinzufügen')) ?></button></details></details>
<details class="tax-notes-step" data-tax-notes-section><summary><?= e($taxText('4. Wofür wurde das Vereinsgeld verwendet?')) ?></summary>
<?php $taxNotesSelect($taxNotesBase.'[funds_use_status]','Beschreibung der Mittelverwendung',['unknown'=>'Noch offen','entered'=>'Mittelverwendung beschreiben'],$taxNotesValue($taxNotesRow,'funds_use_status','unknown'),['data-tax-section-choice'=>'entered']); ?>
<details data-tax-section-body <?= $taxNotesValue($taxNotesRow,'funds_use_status')==='entered'?'open':'' ?>><summary><?= e($taxText('Verwendung beschreiben')) ?></summary><label><?= e($taxText('Verwendung und Zusammenhang mit den Vereinszwecken')) ?><textarea class="form-control" name="<?= e($taxNotesBase.'[funds_use_note]') ?>" rows="5" maxlength="6000" data-tax-required placeholder="<?= e($taxText('Zum Beispiel Veranstaltungen, Vereinsräume oder Anschaffungen; passende Nachweise nennen.')) ?>"><?= e($taxNotesValue($taxNotesRow,'funds_use_note')) ?></textarea></label></details></details>
<details class="tax-notes-step" data-tax-notes-section <?=!empty($taxNotesExpand[$taxNotesYear]['corrections'])?'open':''?>><summary><?= e($taxText('5. Sind steuerliche Abweichungen zu berücksichtigen?')) ?></summary>
<p><?= e($taxText('Aus der geprüften Buchhaltung oder Steuerberatung übernehmen. Unklar? „Weiß ich nicht – prüfen lassen“ stehen lassen.')) ?></p>
<?php $taxNotesSelect($taxNotesBase.'[corrections_status]','Korrekturenstand',['unknown'=>'Noch offen','none'=>'Nach eigener Prüfung keine Korrekturen','listed'=>'Korrekturen einzeln erfassen'],$taxNotesValue($taxNotesRow,'corrections_status','unknown'),['data-tax-section-choice'=>'listed']); ?>
<details data-tax-section-body <?= ($taxNotesValue($taxNotesRow,'corrections_status')==='listed'||!empty($taxNotesExpand[$taxNotesYear]['corrections']))?'open':'' ?>><summary><?= e($taxText('Buchhaltungsdetails: steuerliche Korrekturen')) ?></summary><div data-tax-notes-list="corrections" data-tax-max="20"><?php $taxNotesCorrections=is_array($taxNotesRow['corrections']??null)?array_slice(array_values($taxNotesRow['corrections']),0,20):[];if(!$taxNotesCorrections)$taxNotesCorrections=[[]];foreach($taxNotesCorrections as $i=>$r)$taxNotesCorrectionRow(is_array($r)?$r:[],(string)$i,$taxNotesYear); ?></div>
<template data-tax-notes-template="corrections"><?php $taxNotesCorrectionRow([],'__INDEX__',$taxNotesYear); ?></template><button type="<?=$annualRowsEnabled?'submit':'button'?>" <?php if($annualRowsEnabled):?>name="annual_tax_rows" value="<?=e('add:corrections:'.$taxNotesYear)?>" formnovalidate<?php endif?> class="btn btn-outline theme-secondary button secondary" data-tax-add-row="corrections"><?= e($taxText('Weitere Korrektur hinzufügen')) ?></button></details></details>
</details>
<?php endforeach ?>
<?php if(empty($taxNotesAutoCase)): ?><p class="muted"><?= e($taxText('Nach der Vorschau das Unterlagenpaket speichern. Hier erfolgt keine Steuerabgabe.')) ?></p><?php endif ?>
